  "WC_Type_Accessible": {"ko":"장애인 화장실","en":"Accessible restroom","ja":"多目的トイレ","zh":"无障碍洗手间","vi":"Nhà vệ sinh cho người khuyết tật","th":"ห้องน้ำสำหรับผู้พิการ","ru":"Туалет для людей с инвалидностью","id":"Toilet difabel"},
  "WC_Hours": {"ko":"이용 시간","en":"Hours","ja":"利用時間","zh":"开放时间","vi":"Giờ mở cửa","th":"เวลาเปิด","ru":"Часы работы","id":"Jam buka"},
  "WC_Map_Soon": {"ko":"층 도면은 준비 중입니다","en":"Floor maps are coming soon","ja":"フロアマップは準備中です","zh":"楼层平面图正在准备中","vi":"Sơ đồ tầng đang được chuẩn bị","th":"แผนผังชั้นกำลังจัดเตรียม","ru":"План этажа скоро появится","id":"Denah lantai sedang disiapkan"},
  "Event_Filter_Show": {"ko":"공연","en":"Performances","ja":"公演","zh":"演出","vi":"Biểu diễn","th":"การแสดง","ru":"Выступления","id":"Pertunjukan"},
  "Event_Filter_Exhibit": {"ko":"전시","en":"Exhibitions","ja":"展示","zh":"展览","vi":"Triển lãm","th":"นิทรรศการ","ru":"Выставки","id":"Pameran"},
