  "Event_None": {"ko":"지금 진행 중인 이벤트가 없습니다","en":"No events right now","ja":"現在開催中のイベントはありません","zh":"目前没有进行中的活动","vi":"Hiện không có sự kiện nào","th":"ขณะนี้ไม่มีอีเวนต์","ru":"Сейчас событий нет","id":"Belum ada acara saat ini"},
  "Building_Select": {"ko":"건물 선택","en":"Choose a building","ja":"建物を選択","zh":"选择建筑","vi":"Chọn tòa nhà","th":"เลือกอาคาร","ru":"Выберите здание","id":"Pilih gedung"},
